sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Calls AssignmentEngine.getAssignmentGroup() then .getEligibleAgents() then .selectBestAgent(); sets assignment_group and assigned_to; calls .logAssignment()
    var category = current.getValue('category');
    var subcategory = current.getValue('subcategory');
    var priority = current.getValue('priority');

    var assignmentEngine = new AssignmentEngine();

    var groups = assignmentEngine.getAssignmentGroup(category, subcategory);
    if (!groups.primary && !groups.backup) return;

    // Try the primary group first; fall back to the backup group when there is no best agent
    var assignmentGroup = groups.primary;
    var eligibleAgents = assignmentEngine.getEligibleAgents(groups.primary, category, priority);
    var bestAgent = assignmentEngine.selectBestAgent(eligibleAgents, priority);

    if (!bestAgent && groups.backup) {
        assignmentGroup = groups.backup;
        eligibleAgents = assignmentEngine.getEligibleAgents(groups.backup, category, priority);
        bestAgent = assignmentEngine.selectBestAgent(eligibleAgents, priority);
    }

    current.setValue('assignment_group', assignmentGroup);

    if (!bestAgent) {
        assignmentEngine.logAssignment(current.getUniqueValue(), assignmentGroup, '','No eligible agent found, routed to group queue', 'fallback_no_match');
        return;
    }

    current.setValue('assigned_to', bestAgent);

    var reason = 'Assigned based on category = ' + category + ', subcategory = ' + subcategory;
    assignmentEngine.logAssignment(current.getUniqueValue(), assignmentGroup, bestAgent, reason, 'initial');

})(current, previous);
